import React, { useState, useEffect } from "react";

const API_BASE = "http://localhost:5000";

function App() {
  const [longUrl, setLongUrl] = useState("");
  const [shortUrl, setShortUrl] = useState("");
  const [urls, setUrls] = useState([]);
  const [searchTerm, setSearchTerm] = useState("");

  const handleSubmit = async (e) => {
    e.preventDefault();
    const res = await fetch(API_BASE + "/api/encode", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ longUrl })
    });
    const data = await res.json();
    setShortUrl(data.shortUrl);
    fetchUrls();
  };

  const fetchUrls = async () => {
    const res = await fetch(API_BASE + "/api/list");
    const data = await res.json();
    setUrls(data);
  };

  useEffect(() => {
    fetchUrls();
  }, []);

  const filteredUrls = urls.filter(u =>
    u.longUrl.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div style={{ padding: "20px", fontFamily: "Arial" }}>
      <h2>🔗 ShortLink - URL Shortener</h2>
      <form onSubmit={handleSubmit}>
        <input
          type="text"
          placeholder="Enter long URL"
          value={longUrl}
          onChange={(e) => setLongUrl(e.target.value)}
          style={{ width: "300px", marginRight: "10px" }}
        />
        <button type="submit">Shorten</button>
      </form>
      {shortUrl && (
        <p>
          Shortened URL: <a href={shortUrl}>{shortUrl}</a>
        </p>
      )}
      <hr />
      <input
        type="text"
        placeholder="Search URLs..."
        onChange={(e) => setSearchTerm(e.target.value)}
      />
      <h4>📃 All URLs</h4>
      <ul>
        {filteredUrls.map((url, i) => (
          <li key={i}>
            <strong>{url.longUrl}</strong> →{" "}
            <a href={url.shortUrl}>{url.shortUrl}</a> | Visits: {url.visits}
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
